from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class IpAddressElement(SchemaObject):
    v4 = SchemaField(name='v4', optional=True, not_null=False)
    v6 = SchemaField(name='v6', optional=True, not_null=False)

    def __init__(self, v4, v6):
        self.v4 = v4
        self.v6 = v6
        super(IpAddressElement, self).__init__()


class IpAddressSet(SchemaObject):
    c_plane_ip_address = SchemaField(name="cPlaneIpAddress", klass=IpAddressElement, many=True, not_null=False)
    u_plane_ip_address = SchemaField(name="uPlaneIpAddress", klass=IpAddressElement, many=True, not_null=False)

    def __init__(self, c_plane_ip_address, u_plane_ip_address):
        self.c_plane_ip_address = c_plane_ip_address
        self.u_plane_ip_address = u_plane_ip_address
        super(IpAddressSet, self).__init__()


class CUgNBIPaddresses(SchemaObject):
    vnf_ip_address = SchemaField(name="vnfIpAddress", optional=True)
    f1_interface = SchemaField(name="f1Interface", klass=IpAddressSet)
    m_plane_ip_address = SchemaField(name="mPlaneIpAddress", klass=IpAddressElement)
    ng_interface = SchemaField(name="ngInterface", klass=IpAddressSet)
    x2_interface = SchemaField(name="x2Interface", klass=IpAddressSet)
    xn_interface = SchemaField(name="xnInterface", klass=IpAddressSet)

    def __init__(self, vnf_ip_address, f1_interface, m_plane_ip_address, ng_interface, x2_interface, xn_interface):
        self.vnf_ip_address = vnf_ip_address
        self.f1_interface = f1_interface
        self.m_plane_ip_address = m_plane_ip_address
        self.ng_interface = ng_interface
        self.x2_interface = x2_interface
        self.xn_interface = xn_interface

        super(CUgNBIPaddresses, self).__init__()


class Amf(SchemaObject):
    ip_address = SchemaField(name="ipAddress", optional=True)
    name = SchemaField(name="name", optional=True)
    ng_link_status = SchemaField(name="ngLinkStatus", optional=True)

    def __init__(self, ip_address, name, ng_link_status):
        self.ip_address = ip_address
        self.name = name
        self.ng_link_status = ng_link_status

        super(Amf, self).__init__()


class CuStatesASMV1(SchemaObject):
    id = SchemaField(name="id", optional=True)
    name = SchemaField(name="name", optional=True)
    mrbts_id = SchemaField(name="mrbtsId", optional=True)
    bts_name = SchemaField(name="btsName", optional=True)
    software_version = SchemaField(name="softwareVersion")
    operational_state = SchemaField(name="operationalState")
    time_zone = SchemaField(name="timeZone")
    type = SchemaField(name="type", optional=True)
    mcc = SchemaField(name="mcc", optional=True)
    mnc = SchemaField(name="mnc", optional=True)
    mnc_length = SchemaField(name="mncLength", optional=True)
    server_ip_address_primary = SchemaField(name="serverIpAddressPrimary")
    server_ip_address_secondary = SchemaField(name="serverIpAddressSecondary", optional=True)
    ip_addresses = SchemaField(name="ipAddresses", klass=CUgNBIPaddresses, not_null=True)
    number_of_alarms = SchemaField(name="numberOfAlarms")
    amfs = SchemaField(name="amfs", klass=Amf, many=True, optional=True)
    nrbts_id = SchemaField(name='nrbtsId')

    def __init__(self, id, name, mrbts_id, bts_name, software_version, operational_state, time_zone, type, mcc, mnc,
                 mnc_length, server_ip_address_primary, server_ip_address_secondary, ip_addresses, number_of_alarms,
                 amfs, nrbts_id):
        self.id = id
        self.name = name
        self.mrbts_id = mrbts_id
        self.bts_name = bts_name
        self.software_version = software_version
        self.operational_state = operational_state
        self.time_zone = time_zone
        self.type = type
        self.mcc = mcc
        self.mnc = mnc
        self.mnc_length = mnc_length
        self.server_ip_address_primary = server_ip_address_primary
        self.server_ip_address_secondary = server_ip_address_secondary
        self.ip_addresses = ip_addresses
        self.number_of_alarms = number_of_alarms
        self.nrbts_id = nrbts_id
        self.amfs = amfs if amfs else []
        super(CuStatesASMV1, self).__init__()
